∀ {a b : ℕ} {Cell : Type} {cellFintype : Fintype Cell} {Node : Type} {nodeFintype : Fintype Node}
  {cellForm : Cell → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ} {cellNode : Cell → Node} {parent : Node → Option Node}
  {rank : Node → ℕ} {eliminated : Node → Finset (Fin a)} {front : Node → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {root : Node} {globalForm : Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ} {Cell_1 : Type} {cellFintype_1 : Fintype Cell_1}
  {Node_1 : Type} {nodeFintype_1 : Fintype Node_1} {cellForm_1 : Cell_1 → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {cellNode_1 : Cell_1 → Node_1} {parent_1 : Node_1 → Option Node_1} {rank_1 : Node_1 → ℕ}
  {eliminated_1 : Node_1 → Finset (Fin a)} {front_1 : Node_1 → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {root_1 : Node_1} {globalForm_1 : Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ},
  { Cell := Cell, cellFintype := cellFintype, Node := Node, nodeFintype := nodeFintype, cellForm := cellForm,
        cellNode := cellNode, parent := parent, rank := rank, eliminated := eliminated, front := front, root := root,
        globalForm := globalForm } =
      { Cell := Cell_1, cellFintype := cellFintype_1, Node := Node_1, nodeFintype := nodeFintype_1,
        cellForm := cellForm_1, cellNode := cellNode_1, parent := parent_1, rank := rank_1, eliminated := eliminated_1,
        front := front_1, root := root_1, globalForm := globalForm_1 } →
    Cell = Cell_1 ∧
      cellFintype ≍ cellFintype_1 ∧
        Node = Node_1 ∧
          nodeFintype ≍ nodeFintype_1 ∧
            cellForm ≍ cellForm_1 ∧
              cellNode ≍ cellNode_1 ∧
                parent ≍ parent_1 ∧
                  rank ≍ rank_1 ∧
                    eliminated ≍ eliminated_1 ∧ front ≍ front_1 ∧ root ≍ root_1 ∧ globalForm = globalForm_1

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    Breakdown.CellCert.CellFormula.IsPressureLayout c r.box r.scalars r.bases C.layout

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsReducedLosses c D A M RD X →
    ∀ j ∈ c.activeSet, ∀ p ∈ Breakdown.SteadyCert.box c.radius, √(X.adjointKernel j) / √c.weightMin ≤ c.adjointQuad j p

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {T : Breakdown.CertCell.TreeEntry D R} {e : ℝ}
  {Y : Breakdown.CertCell.CellLayerEntries D R T},
  Breakdown.CertCell.CellLayerEntryConditions D R T e Y →
    Breakdown.CertCell.PotentialEntryConditions D R Y.assembly Y.coupling
      (Breakdown.CertCell.Assembly.InRowRange Y.rows)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM} {cForm : ℝ} {q : Fin k → ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space} {κ : Fin k → ℝ} {F : ℝ → Breakdown.Space → Breakdown.Space}
  {perturbation : Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) v G H g}
  {right_measurable : MeasureTheory.AEStronglyMeasurable (fun z => F z.1 z.2) MeasureTheory.volume}
  {right_periodic : Breakdown.IsTimePeriodic F} {right_finite : (Breakdown.periodLIntegral fun σ y => ‖F σ y‖ ^ 2) < ⊤}
  {right_side : Breakdown.IsRightSide (D.cert.model q) D.cert.actuator κ v G g F}
  {pos_finite : (D.withFormCoercivity cForm).formPos q v G H < ⊤} {v_1 : ℝ → Breakdown.Space → Breakdown.Space}
  {G_1 : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H_1 : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g_1 : ℝ → Breakdown.Space → Breakdown.Space} {κ_1 : Fin k → ℝ} {F_1 : ℝ → Breakdown.Space → Breakdown.Space}
  {perturbation_1 : Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) v_1 G_1 H_1 g_1}
  {right_measurable_1 : MeasureTheory.AEStronglyMeasurable (fun z => F_1 z.1 z.2) MeasureTheory.volume}
  {right_periodic_1 : Breakdown.IsTimePeriodic F_1}
  {right_finite_1 : (Breakdown.periodLIntegral fun σ y => ‖F_1 σ y‖ ^ 2) < ⊤}
  {right_side_1 : Breakdown.IsRightSide (D.cert.model q) D.cert.actuator κ_1 v_1 G_1 g_1 F_1}
  {pos_finite_1 : (D.withFormCoercivity cForm).formPos q v_1 G_1 H_1 < ⊤},
  { v := v, G := G, H := H, g := g, κ := κ, F := F, perturbation := perturbation, right_measurable := right_measurable,
        right_periodic := right_periodic, right_finite := right_finite, right_side := right_side,
        pos_finite := pos_finite } =
      { v := v_1, G := G_1, H := H_1, g := g_1, κ := κ_1, F := F_1, perturbation := perturbation_1,
        right_measurable := right_measurable_1, right_periodic := right_periodic_1, right_finite := right_finite_1,
        right_side := right_side_1, pos_finite := pos_finite_1 } →
    v = v_1 ∧ G = G_1 ∧ H = H_1 ∧ g = g_1 ∧ κ = κ_1 ∧ F = F_1

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S →
    ∀ (j : Fin R.creditCount) (K : Fin D.mesh.count) (ι : ℤ × ℤ),
      Breakdown.CertCell.labelHarmonic D.azimuthOrder ι = Breakdown.CertCell.flipLabel (R.creditPatch j).label ∨
          Breakdown.CertCell.labelHarmonic D.azimuthOrder ι = -Breakdown.CertCell.flipLabel (R.creditPatch j).label →
        ι ∉ D.mesh.resolved K ∧ ι ∉ D.mesh.band K

