  {slope_1 slopeInverse_1 : Matrix (Fin k) (Fin k) ℝ} {slopeOffset_1 : Fin k → ℝ}
  {defectBound_1 defectBallBound_1 : (Fin k → ℝ) → ℝ} {weight_1 : ℝ} {weightFn_1 : Breakdown.Space → ℝ}
  {weightMax_1 coerciveL2_1 coerciveBall_1 coercivePin_1 coerciveTotal_1 ballRadius_1 decay_1 periodMax_1 : ℝ}
  {twist_1 : ℕ} {actuatorBound_1 formBound_1 defectMax_1 sizeBound_1 supBound_1 : ℝ},
  { symmetries := symmetries, center := center, radius := radius, period := period, profile := profile,
        pressure := pressure, multiplier := multiplier, target := target, actuator := actuator, pin := pin,
        slope := slope, slopeInverse := slopeInverse, slopeOffset := slopeOffset, defectBound := defectBound,
        defectBallBound := defectBallBound, weight := weight, weightFn := weightFn, weightMax := weightMax,
        coerciveL2 := coerciveL2, coerciveBall := coerciveBall, coercivePin := coercivePin,
        coerciveTotal := coerciveTotal, ballRadius := ballRadius, decay := decay, periodMax := periodMax,
        twist := twist, actuatorBound := actuatorBound, formBound := formBound, defectMax := defectMax,
        sizeBound := sizeBound, supBound := supBound } =
      { symmetries := symmetries_1, center := center_1, radius := radius_1, period := period_1, profile := profile_1,
        pressure := pressure_1, multiplier := multiplier_1, target := target_1, actuator := actuator_1, pin := pin_1,
        slope := slope_1, slopeInverse := slopeInverse_1, slopeOffset := slopeOffset_1, defectBound := defectBound_1,
        defectBallBound := defectBallBound_1, weight := weight_1, weightFn := weightFn_1, weightMax := weightMax_1,
        coerciveL2 := coerciveL2_1, coerciveBall := coerciveBall_1, coercivePin := coercivePin_1,
        coerciveTotal := coerciveTotal_1, ballRadius := ballRadius_1, decay := decay_1, periodMax := periodMax_1,
        twist := twist_1, actuatorBound := actuatorBound_1, formBound := formBound_1, defectMax := defectMax_1,
        sizeBound := sizeBound_1, supBound := supBound_1 } →
    symmetries = symmetries_1 ∧
