∀ {K : Breakdown.CellCert.CellAnalysis.CellBox} {resolved : Finset (ℤ × ℤ)}
  {coef : ℤ × ℤ → ℝ × ℝ → Breakdown.CertCell.ModeCoefficients} {ch : Breakdown.CertCell.ModeCharges}
  {T : Breakdown.CertCell.CellCalculus.LeafValues},
  Breakdown.CertCell.CellCalculus.IsLeafValues K resolved coef ch T → ∀ ι ∈ resolved, 0 ≤ T.curlHessFloor ι

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    r.rows.multiplierMatrix = RD.mix * Breakdown.CellCert.CellSystem.testMultiplierOf c RD r * RD.mix.transpose

∀ {k N slots : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {K₀ : Fin M.cellCount}
  {R : Breakdown.CellCert.CellAnalysis.CellRows N slots k},
  Breakdown.CellCert.GivenModel.IsRowsInstance c M RD K₀ R → ∀ a ∈ R.rowSet, R.rowModeOf a = ↑(RD.harmonic a)

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    Breakdown.CellCert.Reduction.IsGivenBases r.box r.baseDegree r.givenBases

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {W : Breakdown.CellCert.Reduction.WeightData},
  Breakdown.CellCert.Reduction.IsWeightTests α c K S W → S.weightFloor ≤ W.symAt K S 0 0 (↑(W.J + 1) * ↑c.order) true

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CellReduction.Instantiation.ProfileShapeEntry k}
  {Pr : Breakdown.CellReduction.Instantiation.PressureShapeEntry k},
  Breakdown.CellReduction.Instantiation.IsPressureShapeEntry D R Pr →
    ∀ (q : Fin k → ℝ) (σ : ℝ) (y : Breakdown.Space),
      D.cert.pressureGrad q σ y = gradient (fun y' => Pr.pressure R q σ y' - ‖D.cert.profile q σ y'‖ ^ 2 / 2) y

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM} {cForm : ℝ} {q : Fin k → ℝ}
  (self : Breakdown.CertCell.AdmissibleTuple D cForm q),
  Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) self.v self.G self.H self.g

∀ {k N slots : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {K₀ : Fin M.cellCount}
  {R : Breakdown.CellCert.CellAnalysis.CellRows N slots k},
  Breakdown.CellCert.GivenModel.IsRowsInstance c M RD K₀ R → c.row = RD.rowField c.order

